import os, json, csv, glob
import numpy as np

N = 26
ROOT = "storage/Inquire/nmap/n26"
OUT_DIR = "storage/noesis/nmap/nudged"

REFS = {
    "Noesis_243": {"sum_r": 2.6342924, "file": "pairs_jaccard_{name}_vs_Noesis_243_tol1e8.json"},
    "Scientia_259": {"sum_r": 2.6358957, "file": "pairs_jaccard_{name}_vs_Scientia_259_tol1e8.json"},
    "Prometheus_298": {"sum_r": 2.6359774, "file": "pairs_jaccard_{name}_vs_Prometheus_298_tol1e8.json"}
}

def load_json(p):
    try:
        with open(p, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return None

def save_json(p, obj):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8') as f:
        json.dump(obj, f, indent=2)

def save_csv(p, rows, header):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    with open(p, 'w', encoding='utf-8', newline='') as f:
        w = csv.writer(f); w.writerow(header); w.writerows(rows)

def find_first(patterns):
    for pat in patterns:
        hits = sorted(glob.glob(pat))
        if hits:
            return hits[0]
    return None

def find_nudged(root=ROOT):
    if not os.path.exists(root): return []
    items = []
    for name in sorted(os.listdir(root)):
        p = os.path.join(root, name)
        if os.path.isdir(p) and name.lower().startswith("nudged"):
            items.append((name, p))
    return items

def load_sum_r_from_summary(folder):
    # Accept ..._summary_tol1e8.json, ..._summary_tol1e08.json, summary_tol1e8.json, summary_tol1e08.json
    cand = [
        find_first([os.path.join(folder, "*_summary_tol1e8.json"),
                    os.path.join(folder, "summary_tol1e8.json")]),
        find_first([os.path.join(folder, "*_summary_tol1e08.json"),
                    os.path.join(folder, "summary_tol1e08.json")])
    ]
    for c in cand:
        if not c: continue
        obj = load_json(c)
        if not obj: continue
        for key in ["sum_r", "sumR", "SigmaR", "sum_of_radii", "sumRadii", "score"]:
            if key in obj:
                try:
                    return float(obj[key])
                except Exception:
                    pass
    return None

def load_sum_r_from_radii(folder):
    # Accept *_radii_tol1e8.txt or *_radii_tol1e08.txt or radii_tol1e8.txt
    p = find_first([os.path.join(folder, "*_radii_tol1e8.txt"),
                    os.path.join(folder, "radii_tol1e8.txt"),
                    os.path.join(folder, "*_radii_tol1e08.txt"),
                    os.path.join(folder, "radii_tol1e08.txt")])
    if not p: return None
    try:
        vals = []
        with open(p, 'r', encoding='utf-8') as f:
            for ln in f:
                ln = ln.strip()
                if not ln: continue
                try:
                    vals.append(float(ln))
                except Exception:
                    pass
        return float(np.sum(np.array(vals, dtype=float))) if vals else None
    except Exception:
        return None

def load_sum_r(folder):
    s = load_sum_r_from_summary(folder)
    if s is not None: return s
    return load_sum_r_from_radii(folder)

def load_jaccard(name, ref_key):
    jp = os.path.join(OUT_DIR, name, REFS[ref_key]["file"].format(name=name))
    obj = load_json(jp)
    if not obj: return None
    return float(obj.get("jaccard", 0.0))

def construct_packing():
    rows = []
    result = {"items": []}
    items = find_nudged()
    for name, path in items:
        sum_r = load_sum_r(path)
        entry = {"name": name, "sum_r": sum_r, "refs": {}}
        for ref_key, ref in REFS.items():
            j = load_jaccard(name, ref_key)
            delta = (None if sum_r is None else (ref["sum_r"] - sum_r))
            entry["refs"][ref_key] = {"pairs_jaccard": j, "delta_sum_r": delta}
            rows.append([
                name,
                "" if sum_r is None else f"{sum_r:.9f}",
                ref_key,
                "" if j is None else f"{j:.9f}",
                "" if delta is None else f"{delta:.9f}"
            ])
        result["items"].append(entry)

    save_json(os.path.join(OUT_DIR, "delta_vs_similarity.json"), result)
    save_csv(os.path.join(OUT_DIR, "delta_vs_similarity.csv"),
             rows,
             header=["name","sum_r","ref","pairs_jaccard","delta_sum_r"])

    # Return a trivial valid pack (analysis-only)
    coords = [0.1,0.3,0.5,0.7,0.9]
    centers = [[x,y] for x in coords for y in coords][:25] + [[0.2,0.2]]
    radii = [0.09999]*25 + [0.0414213]
    return np.array(centers, dtype=float), np.array(radii, dtype=float)
